function RoadmapDemo() {
  const [items, setItems] = useState<RoadmapItem[]>([
    {
      id: "views",
      title: "Saved views",
      description: "Return to a useful collection of filters.",
      status: "planned",
      votes: 2,
      voted: false,
    },
    {
      id: "keyboard",
      title: "Keyboard navigation",
      description: "Move through the workspace without a pointer.",
      status: "in-progress",
      votes: 4,
      voted: false,
    },
    {
      id: "export",
      title: "Project export",
      description: "Take your project data with you.",
      status: "shipped",
      votes: 3,
      voted: false,
    },
  ])
  return (
    <Roadmap
      title="What’s next"
      description="Example roadmap; votes update locally."
      items={items}
      onVote={async (id) =>
        setItems((previous) =>
          previous.map((item) =>
            item.id === id
              ? {
                  ...item,
                  voted: !item.voted,
                  votes: (item.votes ?? 0) + (item.voted ? -1 : 1),
                }
              : item
          )
        )
      }
    />
  )
}
